INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES
('bible-tea', 'playlist', 'pl-beginners', 'es', 'name', 'Empieza Aquí'),
('bible-tea', 'playlist', 'pl-beginners', 'es', 'description', '¿Nuevo en la Biblia? Estas 10 historias te darán la base.'),
('bible-tea', 'playlist', 'pl-jesus', 'es', 'name', 'La Historia de Jesús'),
('bible-tea', 'playlist', 'pl-jesus', 'es', 'description', 'Del pesebre a la tumba vacía. Sigue la vida de la persona más influyente que jamás haya existido.'),
('bible-tea', 'playlist', 'pl-miracles', 'es', 'name', 'Milagros y Maravillas'),
('bible-tea', 'playlist', 'pl-miracles', 'es', 'description', 'Mares abriéndose, fuego del cielo y muertos volviendo a la vida. Dios en acción.'),
('bible-tea', 'playlist', 'pl-drama', 'es', 'name', 'Drama Máximo'),
('bible-tea', 'playlist', 'pl-drama', 'es', 'description', 'Traiciones, giros inesperados y momentos impactantes. La Biblia va CON TODO.'),
('bible-tea', 'playlist', 'pl-courage', 'es', 'name', 'Coraje Bajo Fuego'),
('bible-tea', 'playlist', 'pl-courage', 'es', 'description', 'Mantenerse firme cuando todo está en juego. Historias de valentía increíble.'),
('bible-tea', 'playlist', 'pl-underdogs', 'es', 'name', 'Historias de Desvalidos'),
('bible-tea', 'playlist', 'pl-underdogs', 'es', 'description', 'Nadie creía en ellos. Demostraron que todos estaban equivocados.'),
('bible-tea', 'playlist', 'pl-love', 'es', 'name', 'Historias de Amor'),
('bible-tea', 'playlist', 'pl-love', 'es', 'description', 'Romance, devoción y amor sacrificial. Las más grandes historias de amor de la Biblia.'),
('bible-tea', 'playlist', 'pl-family', 'es', 'name', 'Drama Familiar'),
('bible-tea', 'playlist', 'pl-family', 'es', 'description', 'Rivalidad entre hermanos, disputas familiares y caos generacional. La cena de Navidad no tiene nada que ver con esto.'),
('bible-tea', 'playlist', 'pl-women', 'es', 'name', 'Mujeres de la Biblia'),
('bible-tea', 'playlist', 'pl-women', 'es', 'description', 'Las mujeres feroces, fieles e intrépidas cuyas historias moldearon la historia — de Débora a María.'),
('bible-tea', 'playlist', 'pl-kings', 'es', 'name', 'Reyes y Reinos'),
('bible-tea', 'playlist', 'pl-kings', 'es', 'description', 'El ascenso y caída de la monarquía de Israel — reyes brillantes, reyes terribles, y el Dios que los sobrevivió a todos.'),
('bible-tea', 'playlist', 'pl-paul', 'es', 'name', 'Las Misiones de Pablo'),
('bible-tea', 'playlist', 'pl-paul', 'es', 'description', 'De perseguidor a apóstol — sigue a Pablo por el Imperio Romano mientras planta iglesias, sobrevive naufragios y cambia el mundo.'),
('bible-tea', 'playlist', 'pl-parables', 'es', 'name', 'Parábolas de Jesús'),
('bible-tea', 'playlist', 'pl-parables', 'es', 'description', 'Las historias que Jesús contó para cambiar la forma de pensar — vívidas, subversivas e imposibles de olvidar.'),
('bible-tea', 'playlist', 'pl-healing', 'es', 'name', 'Sanación y Restauración'),
('bible-tea', 'playlist', 'pl-healing', 'es', 'description', 'Cada milagro de sanación — ojos ciegos abiertos, muertos resucitados y cuerpos restaurados.'),
('bible-tea', 'playlist', 'pl-prophets', 'es', 'name', 'Profetas y Visiones'),
('bible-tea', 'playlist', 'pl-prophets', 'es', 'description', 'Zarza ardiente, burras que hablan y visiones apocalípticas — los encuentros más salvajes con Dios en las Escrituras.'),
('bible-tea', 'playlist', 'pl-exodus-full', 'es', 'name', 'El Éxodo Completo'),
('bible-tea', 'playlist', 'pl-exodus-full', 'es', 'description', 'El viaje completo desde la esclavitud en Egipto hasta el borde de la Tierra Prometida — plagas, milagros, rebelión y 40 años en el desierto.'),
('bible-tea', 'playlist', 'pl-david', 'es', 'name', 'La Historia Completa de David'),
('bible-tea', 'playlist', 'pl-david', 'es', 'description', 'De pastor a guerrero a rey imperfecto — el arco completo del más grande y complicado gobernante de Israel.'),
('bible-tea', 'playlist', 'pl-passion', 'es', 'name', 'La Pasión'),
('bible-tea', 'playlist', 'pl-passion', 'es', 'description', 'Las últimas horas de Jesús — traición, juicio, crucifixión y la tumba vacía. La historia que lo cambió todo.'),
('bible-tea', 'playlist', 'pl-acts', 'es', 'name', 'Hechos: Iglesia en Llamas'),
('bible-tea', 'playlist', 'pl-acts', 'es', 'description', 'El nacimiento explosivo de la iglesia primitiva — de Pentecostés a Pablo en Roma. Milagros, persecución y crecimiento imparable.'),
('bible-tea', 'playlist', 'pl-kids', 'es', 'name', 'Historias Bíblicas para Niños'),
('bible-tea', 'playlist', 'pl-kids', 'es', 'description', 'Las historias bíblicas más queridas y aptas para toda la familia — perfectas para escuchar antes de dormir o en viajes.'),
('bible-tea', 'playlist', 'pl-quick', 'es', 'name', 'Escuchas Rápidas'),
('bible-tea', 'playlist', 'pl-quick', 'es', 'description', 'Historias cortas y directas que puedes terminar de una sentada — perfectas para el camino al trabajo o una pausa para café.'),
('bible-tea', 'playlist', 'pl-deep', 'es', 'name', 'Inmersiones Profundas'),
('bible-tea', 'playlist', 'pl-deep', 'es', 'description', 'Narrativas épicas de varios capítulos que exigen tu atención completa — las historias más complejas de la Biblia.'),
('bible-tea', 'playlist', 'pl-promises', 'es', 'name', 'Promesas de Dios'),
('bible-tea', 'playlist', 'pl-promises', 'es', 'description', 'Cada pacto y promesa importante — del arcoíris a la tumba vacía. Dios cumple Su palabra.'),
('bible-tea', 'playlist', 'pl-angels', 'es', 'name', 'Ángeles y lo Sobrenatural'),
('bible-tea', 'playlist', 'pl-angels', 'es', 'description', 'Zarza ardiente, mensajeros angelicales, visiones celestiales y guerra espiritual — los momentos más increíbles de la Biblia.'),
('bible-tea', 'playlist', 'pl-battles', 'es', 'name', 'Guerra y Batallas'),
('bible-tea', 'playlist', 'pl-battles', 'es', 'description', 'Asedios, emboscadas y probabilidades imposibles — cada gran conflicto militar en la Biblia.'),
('bible-tea', 'playlist', 'pl-faith', 'es', 'name', 'Fe Bajo Presión'),
('bible-tea', 'playlist', 'pl-faith', 'es', 'description', 'Cuando todo está en juego — historias de personas que confiaron en Dios cuando no tenía ningún sentido.'),
('bible-tea', 'playlist', 'pl-leadership', 'es', 'name', 'Lecciones de Liderazgo'),
('bible-tea', 'playlist', 'pl-leadership', 'es', 'description', 'Lo que se necesita para liderar al pueblo de Dios — lo bueno, lo malo y los fracasos espectaculares.'),
('bible-tea', 'playlist', 'pl-betrayal', 'es', 'name', 'Traición y Redención'),
('bible-tea', 'playlist', 'pl-betrayal', 'es', 'description', 'Hermanos traidores, votos rotos y regresos espectaculares — las caídas y restauraciones más dramáticas de la Biblia.'),
('bible-tea', 'playlist', 'pl-christmas', 'es', 'name', 'La Historia de Navidad'),
('bible-tea', 'playlist', 'pl-christmas', 'es', 'description', 'La narrativa completa del nacimiento — desde la sorpresa de Zacarías hasta la huida a Egipto. La verdadera historia de Navidad.'),
('bible-tea', 'playlist', 'pl-wilderness', 'es', 'name', 'El Desierto'),
('bible-tea', 'playlist', 'pl-wilderness', 'es', 'description', 'Vagando por el desierto, pruebas divinas y aprendiendo a confiar — historias forjadas en el páramo.'),
('bible-tea', 'playlist', 'pl-hope', 'es', 'name', 'Cuando Necesitas Esperanza'),
('bible-tea', 'playlist', 'pl-hope', 'es', 'description', 'Para los días difíciles — historias de rescate, restauración y nuevos comienzos que te recuerdan que no se ha terminado.'),
('bible-tea', 'playlist', 'pl-joshua', 'es', 'name', 'La Conquista de Josué'),
('bible-tea', 'playlist', 'pl-joshua', 'es', 'description', 'La campaña completa por la Tierra Prometida — desde cruzar el Jordán hasta el desafío final.'),
('bible-tea', 'playlist', 'pl-judges', 'es', 'name', 'Jueces: Era del Caos'),
('bible-tea', 'playlist', 'pl-judges', 'es', 'description', 'Israel sin rey — un ciclo creciente de rebelión, opresión y héroes imperfectos. Se pone intenso.'),
('bible-tea', 'playlist', 'pl-easter', 'es', 'name', 'Semana Santa'),
('bible-tea', 'playlist', 'pl-easter', 'es', 'description', 'De la Última Cena a la Resurrección. La semana más importante de la historia.'),
('bible-tea', 'playlist', 'pl-exodus', 'es', 'name', 'La Gran Escapada'),
('bible-tea', 'playlist', 'pl-exodus', 'es', 'description', 'Esclavitud, plagas, un mar partiéndose por la mitad y supervivencia en el desierto. La película de acción original.'),
('bible-tea', 'playlist', 'pl-abraham', 'es', 'name', 'El Viaje de Abraham'),
('bible-tea', 'playlist', 'pl-abraham', 'es', 'description', 'De una llamada inesperada al padre de las naciones. Sigue la aventura salvaje de fe, mentiras y promesas de Abraham.'),
('bible-tea', 'playlist', 'pl-jacob', 'es', 'name', 'La Saga de Jacob'),
('bible-tea', 'playlist', 'pl-jacob', 'es', 'description', 'La historia de transformación definitiva. Un estafador lucha con Dios y se convierte en el padre de Israel.'),
('bible-tea', 'playlist', 'pl-second-chances', 'es', 'name', 'Segundas Oportunidades'),
('bible-tea', 'playlist', 'pl-second-chances', 'es', 'description', '¿La regaste? Ellos también. Historias sobre gracia, perdón y nuevos comienzos.'),
('bible-tea', 'playlist', 'pl-relationships', 'es', 'name', 'Metas de Relación'),
('bible-tea', 'playlist', 'pl-relationships', 'es', 'description', 'Amor a primera vista, 14 años de espera y lealtad inquebrantable. El amor antiguo pega diferente.');
